263	/* ALARM chip: always visible (opens AI/alarm page); "告警!" when active. */
264	static void refresh_alarm_chip(void)
265	{
266	    const vg_alarm_t * a;
267	    lv_obj_t * lab;
268	
269	    if(s_chip_alarm == NULL) return;
270	
271	    a = vg_model_get_active_alarm();
272	    lab = (lv_obj_t *)lv_obj_get_user_data(s_chip_alarm);
273	    lv_obj_remove_flag(s_chip_alarm, LV_OBJ_FLAG_HIDDEN);
274	
275	    if(a == NULL || !a->active) {
276	        set_chip(s_chip_alarm, "告警", VG_SEV_OK);
277	        lv_obj_set_style_bg_opa(s_chip_alarm, LV_OPA_TRANSP, 0);
278	        if(lab) lv_obj_set_style_text_color(lab, vg_color_muted(), 0);
279	        return;
280	    }
281	
282	    set_chip(s_chip_alarm, "告警!", a->severity);
283	    if(a->acked || a->muted) {
284	        lv_obj_set_style_bg_opa(s_chip_alarm, LV_OPA_TRANSP, 0);
285	        if(lab) lv_obj_set_style_text_color(lab, vg_color_muted(), 0);
286	    }
287	    else {
288	        lv_obj_set_style_bg_opa(s_chip_alarm, LV_OPA_30, 0);
289	        if(lab) {
290	            lv_obj_set_style_text_color(lab, vg_color_severity(a->severity), 0);
291	        }
292	    }
293	}
