362	static bool nav_allowed(vg_page_id_t id, const char ** toast_out)
363	{
364	    switch(id) {
365	        case VG_PAGE_TREND:
366	        case VG_PAGE_DIAGNOSIS:
367	        case VG_PAGE_LOGS:
368	        case VG_PAGE_SYSTEM:
369	        case VG_PAGE_ADD_SENSOR:
370	            if(toast_out) *toast_out = "阶段 2 提供";
371	            return false;
372	        case VG_PAGE_OTA:
373	            if(toast_out) *toast_out = "阶段 3 提供";
374	            return false;
375	        default:
376	            return true;
377	    }
378	}
