380	void vg_nav_goto(vg_page_id_t id, const void * args)
381	{
382	    const char * toast;
383	
384	    if(id >= VG_PAGE_COUNT) return;
385	    if(!nav_allowed(id, &toast)) {
386	        vg_shell_toast(toast);
387	        return;
388	    }
389	
390	    /* First paint (shell just created): do not push phantom back entry */
391	    if(s_content && lv_obj_get_child_count(s_content) == 0 && id == VG_PAGE_HOME) {
392	        s_stack_n = 0;
393	        s_current = id;
394	        create_page(id, args);
395	        return;
396	    }
397	
398	    if(s_stack_n < VG_NAV_STACK_MAX && id != s_current) {
399	        s_stack[s_stack_n].id = s_current;
400	        s_stack[s_stack_n].args_copy = NULL;
401	        s_stack_n++;
402	    }
403	    s_current = id;
404	    create_page(id, args);
405	}
