407	void vg_nav_back(void)
408	{
409	    /* Modal wins over navigation: back/Esc closes the confirm dialog first. */
410	    if(vg_confirm_dialog_is_open()) {
411	        vg_confirm_dialog_close();
412	        return;
413	    }
414	    if(s_stack_n <= 0) {
415	        if(s_current != VG_PAGE_HOME) {
416	            s_current = VG_PAGE_HOME;
417	            create_page(VG_PAGE_HOME, NULL);
418	        }
419	        return;
420	    }
421	    s_stack_n--;
