126	static int board_discover_scan_start(int addr_min, int addr_max)
127	{
128	  pthread_t tid;
129	  pthread_attr_t attr;
130	
131	  if(g_scan_thread_active || g_scan_status == VG_SCAN_RUNNING ||
132	     g_apply_thread_active || g_apply_status == VG_SCAN_RUNNING) {
133	    return -EBUSY;
134	  }
135	
136	  if(addr_min < 1) {
137	    addr_min = CONFIG_VG_HMI_DISCOVER_ADDR_MIN;
138	  }
139	  if(addr_max > 247) {
140	    addr_max = CONFIG_VG_HMI_DISCOVER_ADDR_MAX;
141	  }
142	  if(addr_min > addr_max) {
143	    return -EINVAL;
144	  }
145	
146	  if(access(vg_hmi_rs485_devpath(), R_OK | W_OK) != 0) {
147	    g_scan_last_rc = -errno;
148	    return -errno;
149	  }
150	
151	  g_scan_amin = addr_min;
152	  g_scan_amax = addr_max;
153	  g_scan_last_rc = 0;
154	  g_scan_status = VG_SCAN_RUNNING;
155	  g_scan_thread_active = true;
156	  g_apply_status = VG_SCAN_IDLE;
157	
158	  pthread_attr_init(&attr);
159	  pthread_attr_setstacksize(&attr, VG_HMI_SCAN_STACKSIZE);
160	  if(pthread_create(&tid, &attr, vg_hmi_scan_thread, NULL) != 0) {
161	    pthread_attr_destroy(&attr);
162	    g_scan_thread_active = false;
163	    g_scan_status = VG_SCAN_IDLE;
164	    g_scan_last_rc = -EIO;
165	    return -EIO;
166	  }
167	
168	  pthread_attr_destroy(&attr);
169	  pthread_detach(tid);
170	  return 0;
171	}
