178	static FAR void *vg_hmi_apply_thread(FAR void *arg)
179	{
180	  FAR struct vg_discover_summary *sum = vg_discover_state();
181	  FAR const char *dev = vg_hmi_rs485_devpath();
182	  int i;
183	  int rc;
184	
185	  (void)arg;
186	
187	  while(vg_bus_try_lock() != 0) {
188	    usleep(50000);
189	  }
190	
191	  if(sum == NULL || sum->n_hits <= 0) {
192	    vg_bus_unlock();
193	    g_apply_last_rc = -ENOENT;
194	    g_apply_status = -1;
195	    g_apply_thread_active = false;
196	    return NULL;
197	  }
198	
199	  /* Scan alone only fills hits; probe+infer before persistence. */
200	  for(i = 0; i < sum->n_hits; i++) {
201	    if(!sum->hits[i].alive) {
202	      continue;
203	    }
204	
205	    rc = vg_reg_probe_slave(sum, dev, CONFIG_VG_HMI_DISCOVER_BAUD,
206	                            sum->hits[i].addr, 3, 32);
207	    if(rc < 0) {
208	      /* Keep going — other slaves may still yield points. */
209	      continue;
210	    }
211	  }
212	
213	  if(sum->n_points == 0) {
214	    vg_point_table_infer(sum);
215	  }
216	
217	  if(sum->n_points <= 0) {
218	    vg_bus_unlock();
219	    g_apply_last_rc = -ENOENT;
220	    g_apply_status = -1;
221	    g_apply_thread_active = false;
222	    return NULL;
223	  }
224	
225	  rc = vg_point_table_apply(sum, CONFIG_VG_DISCOVER_POINTS_PATH,
226	                            CONFIG_VG_CONFIG_BASEDIR, true);
227	  vg_bus_unlock();
228	  g_apply_last_rc = rc;
229	  g_apply_status = (rc == 0) ? VG_SCAN_DONE : -1;
230	  g_apply_thread_active = false;
231	  return NULL;
232	}
