273	static int board_get_slaves(vg_ui_slave_t *out, int max)
274	{
275	  FAR const struct vg_discover_summary *sum = vg_discover_state();
276	  uint8_t persisted[VG_DISCOVER_MAX_SLAVES];
277	  int i;
278	  int n = 0;
279	  int persisted_n = 0;
280	
281	  if(out == NULL || max <= 0) {
282	    return 0;
283	  }
284	
285	  if(sum != NULL) {
286	    for(i = 0; i < sum->n_hits && n < max; i++) {
287	      if(!sum->hits[i].alive) {
288	        continue;
289	      }
290	
291	      out[n].addr = sum->hits[i].addr;
292	      out[n].probe_reg = sum->hits[i].probe_reg;
293	      snprintf(out[n].label, sizeof(out[n].label), "addr=%u",
294	               (unsigned)sum->hits[i].addr);
295	      n++;
296	    }
297	  }
298	
299	  if(n > 0) {
300	    return n;
301	  }
302	
303	  /* Cold start: last confirmed table, not mock 24. Retry — FAT may
304	   * still be settling when vghmi is task_create'd. */
305	  for(i = 0; i < 10 && persisted_n <= 0; i++) {
306	    persisted_n = vg_point_table_read_slaves(CONFIG_VG_DISCOVER_POINTS_PATH,
307	                                            persisted, VG_DISCOVER_MAX_SLAVES);
308	    if(persisted_n > 0) {
309	      break;
310	    }
311	
312	    usleep(100000);
313	  }
314	  if(persisted_n <= 0) {
315	    return 0;
316	  }
317	
318	  if(persisted_n > max) {
319	    persisted_n = max;
320	  }
321	
322	  for(i = 0; i < persisted_n; i++) {
323	    out[n].addr = persisted[i];
324	    out[n].probe_reg = 0;
325	    snprintf(out[n].label, sizeof(out[n].label), "addr=%u",
326	             (unsigned)persisted[i]);
327	    n++;
328	  }
329	
330	  return n;
331	}
