333	static int pick_latest_daily(FAR char *path, size_t path_sz)
334	{
335	  DIR *dir;
336	  struct dirent *ent;
337	  char best[64];
338	  char candidate[128];
339	
340	  best[0] = '\0';
341	
342	  dir = opendir(CONFIG_VG_HMI_REPORT_DIR);
343	  if(dir == NULL) {
344	    return -errno;
345	  }
346	
347	  while((ent = readdir(dir)) != NULL) {
348	    if(strncmp(ent->d_name, "daily-", 6) != 0) {
349	      continue;
350	    }
351	    if(strstr(ent->d_name, ".md") == NULL) {
352	      continue;
353	    }
354	    if(best[0] == '\0' || strcmp(ent->d_name, best) > 0) {
355	      strncpy(best, ent->d_name, sizeof(best) - 1);
356	      best[sizeof(best) - 1] = '\0';
357	    }
358	  }
359	
360	  closedir(dir);
361	
362	  if(best[0] == '\0') {
363	    return -ENOENT;
364	  }
365	
366	  snprintf(candidate, sizeof(candidate), "%s/%s",
367	           CONFIG_VG_HMI_REPORT_DIR, best);
368	  if(path != NULL && path_sz > 0) {
369	    snprintf(path, path_sz, "%s", candidate);
370	  }
371	
372	  return 0;
373	}
