375	static int board_read_latest_report(char *body, size_t body_sz,
376	                                    char *path, size_t path_sz)
377	{
378	  char file_path[128];
379	  int fd;
380	  ssize_t n;
381	  size_t total = 0;
382	
383	  if(pick_latest_daily(file_path, sizeof(file_path)) != 0) {
384	    if(path != NULL && path_sz > 0) {
385	      snprintf(path, path_sz, "%s/daily-*.md", CONFIG_VG_HMI_REPORT_DIR);
386	    }
387	    if(body != NULL && body_sz > 0) {
388	      snprintf(body, body_sz,
389	               "暂无日报文件。\n\n路径: %s\n(需 net+emmc 预设落盘)",
390	               CONFIG_VG_HMI_REPORT_DIR);
391	    }
392	    return -ENOENT;
393	  }
394	
395	  if(path != NULL && path_sz > 0) {
396	    snprintf(path, path_sz, "%s", file_path);
397	  }
398	
399	  if(body == NULL || body_sz == 0) {
400	    return 0;
401	  }
402	
403	  fd = open(file_path, O_RDONLY);
404	  if(fd < 0) {
405	    snprintf(body, body_sz, "无法打开: %s (%d)", file_path, errno);
406	    return -errno;
407	  }
408	
409	  while(total + 1 < body_sz) {
410	    n = read(fd, body + total, body_sz - 1 - total);
411	    if(n <= 0) {
412	      break;
413	    }
414	    total += (size_t)n;
415	  }
416	
417	  close(fd);
418	  body[total] = '\0';
419	  return 0;
420	}
