554	static FAR void *vg_hmi_acq_thread(FAR void *arg)
555	{
556	  static int live_ok_logs;
557	  (void)arg;
558	
559	  for(;;) {
560	    struct vg_discover_summary live;
561	    int i;
562	    int n;
563	    int ok = 0;
564	    float a1 = 0.0f;
565	
566	    if(board_bus_busy()) {
567	      usleep(200000);
568	      continue;
569	    }
570	
571	    n = vg_live_points_copy(&live);
572	    if(n < 0) {
573	      n = 0;
574	    }
575	    if(n > VG_LIVE_MAX) {
576	      n = VG_LIVE_MAX;
577	    }
578	
579	    if(n <= 0) {
580	      g_live_n = 0;
581	      write_live_snapshot(&live, 0);
582	      usleep(500000);
583	      continue;
584	    }
585	
586	    if(vg_bus_try_lock() != 0) {
587	      usleep(200000);
588	      continue;
589	    }
590	
591	    {
592	      uint16_t raws[VG_LIVE_MAX];
593	      uint8_t oks[VG_LIVE_MAX];
594	      int rc;
595	
596	      rc = vg_discover_poll_points(vg_hmi_rs485_devpath(),
597	                                   CONFIG_VG_HMI_DISCOVER_BAUD,
598	                                   live.points, n,
599	                                   raws, oks,
600	                                   CONFIG_VG_HMI_DISCOVER_INTER_MS);
601	      vg_bus_unlock();
602	      if(rc != 0) {
603	        printf("vghmi: live open failed rc=%d\n", rc);
604	        for(i = 0; i < n; i++) {
605	          g_live_on[i] = 0;
606	        }
607	        g_live_n = n;
608	        write_live_snapshot(&live, n);
609	        usleep(500000);
610	        continue;
611	      }
612	
613	      for(i = 0; i < n; i++) {
614	        FAR const struct vg_point_entry *p = &live.points[i];
615	        int signed_v = (strcmp(p->dtype, "uint16") != 0);
616	
617	        if(oks[i]) {
618	          float v = signed_v ? ((float)(int16_t)raws[i] * p->scale)
619	                             : ((float)raws[i] * p->scale);
620	          g_live_v[i] = v;
621	          g_live_on[i] = 1;
622	          ok++;
623	          if(p->addr == 1 && p->reg == 0) {
624	            a1 = v;
625	          }
626	        }
627	        else {
628	          g_live_on[i] = 0;
629	        }
630	      }
631	    }
632	
633	    g_live_n = n;
634	    write_live_snapshot(&live, n);
635	    if(ok > 0) {
636	      if(live_ok_logs < 8) {
637	        printf("vghmi: live ok=%d/%d a1=%.1f\n", ok, n, (double)a1);
638	        live_ok_logs++;
639	      }
640	    }
641	    else if(live_ok_logs == 0) {
642	      printf("vghmi: live ok=0/%d a1=0.0\n", n);
643	      live_ok_logs = -1;
644	    }
645	    usleep(200000);
646	  }
647	
648	  return NULL;
649	}
