void vg_model_set_scenario(vg_scenario_t s)
{
    if(s < VG_SCENARIO_NORMAL || s > VG_SCENARIO_OTA) s = VG_SCENARIO_NORMAL;
    apply_scenario(s);
    notify_all();
}

