/****************************************************************************
 * app/velaguard/vg_net_policy.h
 *
 * Pure failover policy. No NuttX, POSIX, or ESP types.
 * Host tests compile this file with gcc.
 ****************************************************************************/

#ifndef __VELAGUARD_VG_NET_POLICY_H
#define __VELAGUARD_VG_NET_POLICY_H

#include <stdbool.h>
#include <stdint.h>

/** 连续 ping 失败达到该次数才判 RJ45 不健康。 */
#define VG_NET_PING_FAIL_N       3
/** 从 Wi-Fi 抢回 RJ45 前，RJ45 需持续健康的窗口（毫秒）。 */
#define VG_NET_RJ45_HOLD_MS      10000u
/** 退避基数：1s，每次指数 ×2。 */
#define VG_NET_BACKOFF_BASE_MS   1000u
/** 退避上限：60s。 */
#define VG_NET_BACKOFF_MAX_MS    60000u
/** Wi-Fi join 连续失败达到该次数时请求 ESP 软复位。 */
#define VG_NET_ESP_RESET_TRIES   5
/** RJ45 稳定在线达到该时长后重置退避指数。 */
#define VG_NET_STABLE_RESET_MS   (5u * 60u * 1000u)

/**
  * @brief  策略层对外状态机（供日志 / vgnet status）。
  * @note   VG_NET_DEGRADED 预留；当前实现主要用 DOWN / ONLINE_*。
  */
typedef enum
{
  VG_NET_DOWN = 0,
  VG_NET_CONNECTING,
  VG_NET_ONLINE_RJ45,
  VG_NET_ONLINE_WIFI,
  VG_NET_DEGRADED
} vg_net_state_t;

/**
  * @brief  活动业务出口（同时只应有一条）。
  */
typedef enum
{
  VG_EGRESS_NONE = 0,
  VG_EGRESS_RJ45,
  VG_EGRESS_WIFI
} vg_egress_t;

/**
  * @brief  TCP 传输后端，与 active_egress 一一对应。
  * @note   rj45 → posix（内核 eth0）；wifi → lesp（ESP AT 套接字）；none → 无 TCP。
  */
typedef enum
{
  VG_TCP_NONE = 0,
  VG_TCP_POSIX,
  VG_TCP_LESP
} vg_tcp_backend_t;

/**
  * @brief  测试注入：覆盖真实采样，便于无拔线验收。
  */
typedef enum
{
  VG_INJECT_AUTO = 0,
  VG_INJECT_FORCE_DOWN,
  VG_INJECT_FORCE_UP
} vg_inject_t;

/**
  * @brief  一拍采样输入（由 vg_net_mgr 填充后交给 step）。
  * @note   rj45_ping_sampled 为 false 时不得累加失败 streak，
  *         否则退避窗口内的空转会提前判挂。
  */
struct vg_net_sample
{
  bool rj45_link;
  bool rj45_has_ip;
  bool rj45_ping_ok;
  bool rj45_ping_sampled;
  bool wifi_assoc;
  bool wifi_has_ip;
};

/**
  * @brief  策略状态与输出标志。
  * @note   调用方每拍读：
  *         - active_egress / tcp_backend：该走哪条 TCP
  *         - tcp_reconnect：本拍是否发生出口切换（须关旧开新）
  *         - request_esp_reset：是否该软复位 ESP（由 note_wifi_join 置位）
  *         - next_rj45_probe_ms / next_wifi_join_ms：下次动作时间
  */
struct vg_net_policy
{
  vg_net_state_t     state;
  vg_egress_t        active_egress;
  vg_tcp_backend_t   tcp_backend;
  bool               tcp_reconnect;
  bool               request_esp_reset;
  vg_inject_t        inject_rj45;
  vg_inject_t        inject_wifi;
  int                jitter_pct;
  unsigned           rj45_ping_fail_streak;
  unsigned           wifi_fail_streak;
  unsigned           rj45_backoff_exp;
  unsigned           wifi_backoff_exp;
  uint64_t           rj45_healthy_since_ms;
  uint64_t           next_rj45_probe_ms;
  uint64_t           next_wifi_join_ms;
  uint64_t           online_since_ms;
  bool               prev_rj45_link;
  bool               initialized;
};

/**
  * @brief  清零并标记策略已初始化。
  * @param  p  策略对象。
  * @retval None
  */

const char * vg_risk_label_zh(const char * risk)
{
    if(risk == NULL) return "未知";
    if(strcmp(risk, "high") == 0) return "高";
    if(strcmp(risk, "medium") == 0) return "中";
    if(strcmp(risk, "low") == 0) return "低";
    return "未知";
}

void vg_model_import_discover_slaves(const vg_ui_slave_t * slaves, int n)
{
    int i;

    if(slaves == NULL || n <= 0) {
        return;
    }

    if(n > VG_SENSOR_MAX) {
        n = VG_SENSOR_MAX;
    }

    s_sensor_n = (uint16_t)n;
    for(i = 0; i < n; i++) {
        vg_sensor_t * s = &s_sensors[i];
        memset(s, 0, sizeof(*s));
        lv_snprintf(s->id, sizeof(s->id), "s_%u", (unsigned)slaves[i].addr);
        lv_snprintf(s->name, sizeof(s->name), "从站%u", (unsigned)slaves[i].addr);
        strncpy(s->type, "温度", sizeof(s->type) - 1);
        strncpy(s->unit, "C", sizeof(s->unit) - 1);
        strncpy(s->formula, "R0", sizeof(s->formula) - 1);
        s->function_code = 3;
        s->length = 1;
        s->data_format = VG_SENSOR_FMT_INT16;
        s->word_order = VG_SENSOR_ORDER_ABCD;
        s->period_ms = 1000;
        s->reg_addr = 0;
        s->slave_addr = slaves[i].addr;
        s->quality_pct = 0;
        s->online = true;
        s->age_sec = 0;
        s->severity = VG_SEV_OK;
        s->value = 0.0f;
        s->base_value = 0.0f;
        s->history_len = 0;
        s->thr_low = 5;
        s->thr_warn = 55;
        s->thr_crit = 70;
    }

    if(s_selected_id[0] == '\0' && s_sensor_n > 0) {
        strncpy(s_selected_id, s_sensors[0].id, sizeof(s_selected_id) - 1);
    }

#ifdef VG_HMI_BOARD
    s_net.acq_ok = true;
#endif

    rebuild_filter();
    notify_all();
}

